import datetime


class Transaction:
    def __init__(self, tx_id, amount, description, date, category=None):
        self.tx_id = tx_id
        # amount: positive for income, negative for expense
        self.amount = amount
        self.description = description
        self.date = date
        self.category = category

    def is_expense(self):
        return self.amount < 0

    def is_income(self):
        return self.amount > 0

